/* Generated by Trae Work — 架构资产管理器升级方案 交互脚本 */
(function () {
  'use strict';

  /* ---------- Mermaid 初始化：配色与文档设计系统对齐 ---------- */
  if (window.mermaid) {
    mermaid.initialize({
      startOnLoad: false,
      securityLevel: 'loose',
      theme: 'base',
      fontFamily: "'Outfit','PingFang SC','Noto Sans CJK SC','Microsoft YaHei',sans-serif",
      themeVariables: {
        // 画布与文字
        background: '#ffffff',
        primaryColor: '#fdf0e8',      // 节点填充：accent 浅橙
        primaryBorderColor: '#c2410c', // 节点描边：accent
        primaryTextColor: '#1c1f26',   // 节点文字：ink
        lineColor: '#6b7280',          // 连线：muted
        secondaryColor: '#e6f4f2',     // 次节点：accent2 浅青
        tertiaryColor: '#f3f1eb',      // 第三色：bg3
        // flowchart
        edgeLabelBackground: '#ffffff',
        clusterBkg: 'rgba(239,236,228,0.55)',
        clusterBorder: '#c9c3b6',
        // class/状态图
        classText: '#1c1f26',
        // gantt
        ganttSectionBkg: '#f3f1eb',
        sectionBkgColor: '#fdf0e8',
        altSectionBkgColor: '#e6f4f2',
        gridColor: '#e2ddd2',
        todayLineColor: '#c2410c',
        taskBkgColor: '#fdf0e8',
        taskTextColor: '#1c1f26',
        taskTextLightColor: '#1c1f26',
        taskTextDarkColor: '#1c1f26',
        taskBorderColor: '#c2410c',
        activeTaskBkgColor: '#c2410c',
        activeTaskBorderColor: '#c2410c',
        doneTaskBkgColor: '#e6f4f2',
        doneTaskBorderColor: '#0f766e',
        // 通用
        textColor: '#1c1f26',
        fontSize: '14px'
      },
      flowchart: { htmlLabels: true, curve: 'basis', padding: 14 },
      gantt: { fontSize: 12, sectionFontSize: 12, numberSectionStyles: 4 },
      themeCSS:
        '.node rect,.node polygon,.node circle{stroke-width:1.4px;}' +
        '.edgePath .path{stroke-width:1.4px;}' +
        '.edgeLabel{font-size:12.5px;}' +
        '.cluster rect{stroke-dasharray:4 3;}' +
        '.messageText{fill:#1c1f26;}'
    });

    var blocks = document.querySelectorAll('pre.mermaid');
    blocks.forEach(function (pre, i) {
      // 保留原始源码，渲染失败时回退显示
      var src = pre.textContent;
      pre.dataset.src = src;
      pre.id = pre.id || ('mermaid-' + i);
    });

    var renderAll = function () {
      try {
        mermaid.run({ querySelector: 'pre.mermaid' }).catch(function (err) {
          console.warn('[mermaid] 批量渲染失败，尝试逐张渲染：', err);
          blocks.forEach(function (pre) {
            var id = pre.id;
            mermaid.render(id + '-svg', pre.dataset.src).then(function (r) {
              pre.innerHTML = r.svg;
            }).catch(function (e) {
              console.error('[mermaid] 图表渲染失败：' + id, e);
              pre.classList.add('mermaid-failed');
              pre.textContent = pre.dataset.src;
            });
          });
        });
      } catch (e) {
        console.error('[mermaid] 初始化异常：', e);
      }
    };

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', renderAll);
    } else {
      renderAll();
    }
  }

  /* ---------- TOC 滚动高亮（scroll-spy） ---------- */
  var tocLinks = Array.prototype.slice.call(document.querySelectorAll('.toc a[href^="#"]'));
  if (tocLinks.length && 'IntersectionObserver' in window) {
    var byId = {};
    tocLinks.forEach(function (a) {
      var sec = document.querySelector(a.getAttribute('href'));
      if (sec) byId[sec.id] = a;
    });

    var spy = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        var link = byId[entry.target.id];
        if (!link) return;
        if (entry.isIntersecting) {
          tocLinks.forEach(function (a) { a.classList.remove('active'); });
          link.classList.add('active');
        }
      });
    }, { rootMargin: '-20% 0px -70% 0px', threshold: 0 });

    Object.keys(byId).forEach(function (id) {
      spy.observe(document.getElementById(id));
    });
  }
})();
